"""One-time archived narrative batch for the seven Raksamala commanders."""
import hashlib, json
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parents[1]; BEST=ROOT/'07_Bestiary'; FOLDER=BEST/'08_Commanders_of_Raksamala_Fortress'; REPORT=BEST/'_audit'; GAME=ROOT/'10_Game Project/Tales of The Dark Time'
BASE='03_Region/10_Raksamala/'; CHAR='05_Karakter & Tokoh Penting/09_Raksamala/'; BHUTA='04_Ras/04_Drahkthar/Bhuta.md'; DHEMIT='04_Ras/04_Drahkthar/Dhemit.md'; KING=BASE+'Faksi & Institusi/Kerajaan Drakhtar.md'; THREAT=BASE+'Threat.md'; P10='08_Story/02_Prologue/10_Jalan_yang_Terbelah.md'
# description, form, personality, fortress, story title, story, race, sources, unresolved
E={
'Asmodea':('Panglima Hasrat dan penjaga Fortress of Lust yang menaklukkan lawan melalui keinginan terdalam mereka. Melodi kutukannya membentuk mimpi indah yang membuat korban menolak bangun, sementara tubuh asli mereka perlahan layu. Ia juga menanam agen bayangan di dunia luar, memperluas pengaruh Raksamala tanpa harus meninggalkan benteng.','Wujud asli Asmodea adalah Succubus tingkat tinggi dengan siluet ramping, sayap gelap, dan suara yang terasa datang dari jarak berbeda. Penampilannya tidak tetap: ia dapat menyerupai orang yang paling dicintai atau dihasrati sasaran. Dalam wujud tiruan, ketidakwajaran tampak pada bayangan yang terlambat bergerak dan mata yang tidak berubah ketika wajah tersenyum. Ia tidak membawa senjata fisik; suara, gestur, dan ilusi menjadi alat utamanya.','Asmodea sabar, manipulatif, dan sangat peka terhadap kebutuhan yang tidak berani diucapkan orang lain. Ia jarang memaksa pada awal pertemuan, lebih suka membuat korban merasa memilih sendiri. Penolakan dianggap tantangan untuk menemukan hasrat yang lebih tersembunyi. Kesetiaannya kepada Sangrahal terikat struktur Raksamala, tetapi ia tetap memiliki kecerdikan pribadi. Ia memperlakukan bawahan sebagai perpanjangan rencana, bukan sahabat, dan membuang penyamaran yang tidak lagi berguna.','Fortress of Lust berupa istana bawah tanah dengan taman gairah palsu, bunga eksotis, air mancur anggur, duri beracun, feromon, dan ilusi personal. Asmodea menguasai pusat labirin mimpi dari wilayah yang dalam catatan lama disebut Taman Layu Raksamala. Benteng ini runtuh bersama kekuasaan Raksamala setelah serangan Hector; narasi penjagaan menggambarkan masa sebelum kehancuran tersebut.','Mimpi yang Memilih Wajah','Seorang penyusup melihat rumah yang telah lama hilang dan mendengar suara keluarganya dari balik pintu. Asmodea tidak muncul sebagai monster; ia memakai wajah seseorang yang paling dirindukan penyusup itu dan memintanya beristirahat.\n\nKetika tangan penyusup menyentuh gagang pintu, ia melihat bayangannya sendiri bergerak terlambat. Ia memejamkan mata dan menyebutkan alasan kedatangannya berulang kali. Taman indah berubah menjadi lorong berduri. Asmodea tertawa dari banyak arah, tetapi korban telah menemukan satu hal yang tidak dapat diberikan ilusi: pilihan untuk tetap berjalan meski kerinduan belum sembuh.','Dhemit',[CHAR+'Asmodea.md',BASE+'Cities & Town/Fortress of Lust.md',DHEMIT,BHUTA,KING,THREAT],['Profil tokoh menyebut Dhemit, sedangkan dokumen benteng menyebut bos Bhuta Succubus/Incubus. Race mengikuti profil; konflik taxonomy belum diselesaikan.']),
'Beelzebub':('Panglima Kerakusan yang menjaga rumah jagal bawah tanah Fortress of Gluttony. Ia memakan materi, sihir, jiwa, bahkan pasukannya sendiri ketika lapar atau marah. Jamuan bentengnya mengubah orang yang menyerah pada makanan menjadi pelayan tanpa akal, menjadikan rasa lapar sebagai pintu menuju kehilangan diri.','Tubuhnya merupakan campuran lalat raksasa dan babi hutan bermata banyak. Perut transparan memperlihatkan jiwa yang dicerna perlahan, sedangkan mulutnya dipenuhi tentakel lintah untuk menyerap sihir. Sayap serangga yang kotor tidak cukup mengangkat seluruh bobotnya, tetapi terus bergetar dan menyebarkan dengung. Kaki besar berakhir pada kuku tebal; lipatan tubuh dipenuhi mulut kecil yang membuka ketika makanan mendekat.','Beelzebub rakus, mudah bosan, dan menilai segala sesuatu berdasarkan apakah dapat dimakan atau diserap. Ia tidak menghargai kesetiaan bawahan karena menganggap mereka cadangan santapan. Kelicikannya muncul melalui jamuan palsu: ia memahami bahwa korban yang lapar akan membenarkan keputusan yang sebelumnya mereka tolak. Ia menjadi agresif ketika sesuatu direbut dari hadapannya, tetapi dapat menunda serangan bila ditawari sumber energi yang lebih besar.','Fortress of Gluttony adalah rumah jagal raksasa dengan dinding daging berdenyut, sungai empedu hitam, dan Dapur Perut Bumi. Beelzebub bersemayam di balik meja jamuan ilusi yang menguji rasa lapar pengunjung. Lokasi ini sesuai sebutan Dapur Darah dalam data lama. Benteng dipahami dalam era sebelum peradaban Raksamala dihancurkan Hector.','Jamuan yang Tidak Disentuh','Seorang tawanan dilemparkan ke ruang jamuan setelah berhari-hari tanpa makanan. Beelzebub menunggu di balik meja, membiarkan aroma hidangan memenuhi ruangan. Ia tidak mengancam; ia hanya menyuruh korban memilih satu suapan.\n\nTawanan itu melihat Jenggala yang telah berubah merangkak di bawah meja dan menyadari harga jamuan tersebut. Ia membalik piring agar aroma tertutup kuah hitam. Beelzebub mengaum, marah bukan karena kehilangan makanan, melainkan karena rasa lapar gagal menguasai keputusan korbannya.','Bhuta',[CHAR+'Beelzebub.md',BASE+'Cities & Town/Fortress of Gluttony.md',BHUTA,KING,THREAT],['Mekanisme perubahan menjadi Dhemit/Jenggala berbeda antara profil dan dokumen benteng; tidak dibuat aturan transformasi gameplay.']),
'Belphegor':('Panglima Kemalasan yang tidak pernah meninggalkan singgasana keraknya. Ia menguasai gravitasi, miasma, dan racun tidur sehingga lawan dikalahkan oleh berat tubuh serta hilangnya kemauan sebelum mencapai dirinya. Diamnya bukan ketidakmampuan; seluruh Fortress of Sloth berfungsi sebagai jangkauan serangannya.','Belphegor berbentuk raksasa gemuk berbatu yang menyatu dengan singgasana. Lapisan kerak menutup punggung dan pinggang, sementara sulur berlendir tumbuh dari celah batu. Gas ungu keluar perlahan dari mulut serta pori tubuhnya. Matanya nyaris selalu tertutup, tetapi singgasana bergetar ketika ia menyadari penyusup. Batas antara tubuh, lumut, jamur, dan batu menjadi sulit dibedakan setelah ia berdiam terlalu lama.','Belphegor apatis, sabar, dan lebih suka membuat lawan menyerah daripada bergerak untuk menghentikan mereka. Ia berbicara seolah setiap tindakan tidak berguna, menanamkan keputusasaan melalui kata-kata yang lambat. Ia tidak mengejar penghinaan dan membiarkan pasukan menjadi sasaran selama benteng tetap bekerja. Sikap ini juga menjadi kelemahannya: ia meremehkan orang yang mampu mempertahankan tujuan di tengah kelelahan dan terlambat menanggapi perubahan cepat.','Fortress of Sloth adalah gua jamur berisi kabut spora ungu, tulang korban tertidur, dan ilusi tempat istirahat. Belphegor menyatu dengan singgasana di Gua Tidur Abadi, sejalan dengan lokasi lama Lorong Tidur Raksamala. Seluruh ruang menguras energi dan kemauan. Konteks ini menggambarkan benteng sebelum keruntuhan Raksamala.','Satu Langkah Lagi','Seorang penyusup melihat tempat tidur bersih di tengah kabut dan berjanji hanya akan duduk sebentar. Suara Belphegor menyebut perjalanan itu sia-sia dan menawarkan akhir tanpa rasa sakit. Lutut penyusup hampir menyentuh kasur.\n\nIa menjatuhkan ransel agar tubuh lebih ringan, lalu mengambil satu langkah. Setelah setiap langkah ia mengulang nama orang yang ingin diselamatkan. Belphegor tetap diam, yakin tekad itu akan habis. Ketika suara langkah mencapai ruang singgasana, untuk pertama kalinya batu di tubuh sang panglima bergerak.','Bhuta',[CHAR+'Belphegor.md',BASE+'Cities & Town/Fortress of Sloth.md',BHUTA,KING,THREAT],['Gravitasi, tidur, miasma, dan keputusasaan belum dipetakan menjadi state/durasi terkalibrasi.']),
'Leviathanus':('Panglima Kedengkian, monster amfibi yang menjaga Fortress of Envy dan menyerang persatuan kelompok. Racunnya memperbesar perbandingan, iri hati, dan dorongan mengkhianati rekan. Ia membenci keindahan daratan serta matahari, lalu memakai gambaran kehidupan sempurna untuk membuat orang lain membenci pilihan mereka sendiri.','Tubuh Leviathanus menyerupai ular laut raksasa dengan sisik gelap dan banyak tentakel bayangan. Mata hijau pucat menonjol dari kepala amfibi, sementara selaput pada leher bergerak ketika ia bernapas. Es tumbuh pada ujung tentakel sebelum dilepaskan bersama bisa. Tubuhnya dapat melingkari akar serta dinding Labirin Ratapan, membuat asal serangan sulit ditemukan. Pantulan cermin memecah wujudnya menjadi banyak sosok yang tampak saling mengawasi.','Leviathanus pendendam, posesif, dan terus membandingkan miliknya dengan kehidupan pihak lain. Ia pandai menemukan rasa tidak aman dalam kelompok dan mengulangnya sampai terdengar seperti kebenaran. Kepada bawahan ia memberi penghargaan yang sengaja tidak setara agar persaingan tumbuh. Ia membenci Ksatria Aqua yang berulang kali mencegatnya di laut. Ketika lawan saling mempercayai tanpa mencari siapa yang lebih unggul, ketenangannya pecah menjadi kemarahan terbuka.','Fortress of Envy tersembunyi di dasar lembah beracun, tersusun dari akar layu, duri, cermin ajaib, dan lantai beracun. Leviathanus menguasai Labirin Ratapan serta Danau Hitam yang disebut data lama. Jalur air memberi akses ke laut tempat ia berhadapan dengan Aqua. Benteng ini merujuk keadaan sebelum kehancuran Raksamala.','Cermin untuk Dua Sahabat','Dua penyusup melihat masa depan berbeda di dalam cermin: satu dipuji sebagai pahlawan, yang lain dilupakan. Leviathanus membisikkan bahwa hanya satu dari mereka yang layak keluar hidup-hidup. Tangan keduanya bergerak menuju senjata.\n\nSalah seorang memecahkan cerminnya sendiri dan meminta rekannya melakukan hal sama. Bayangan sempurna runtuh menjadi pecahan yang hanya memperlihatkan wajah lelah mereka. Leviathanus menyerang dari danau, marah karena perbandingan itu kehilangan permukaan tempat tumbuh.','Bhuta',[CHAR+'Leviathanus.md',BASE+'Cities & Town/Fortress of Envy.md',BHUTA,KING,THREAT],['Profil menggambarkan ular laut bertentakel; dokumen benteng menyebut Bhuta kembar siam. Wujud belum direkonsiliasi. Pencurian stat/skill bukan mekanik yang ditambahkan.']),
'Luciferus':('Panglima Keangkuhan dan jenderal terkuat di bawah Sangrahal. Ia menguasai sihir kosmik serta ilusi yang menyerang harga diri. Luciferus menganggap manusia dan elf sebagai hama; hanya lawan yang mencapai takhtanya tanpa berlutut dianggap cukup berarti untuk menerima serangan langsung.','Luciferus adalah Bhuta bersayap enam dengan cahaya emas yang telah terkorupsi. Wajahnya tampak sempurna dan tenang, sedangkan mata serta aura membuat orang di hadapannya merasa kecil. Zirah gelap mengikuti bentuk tubuh tanpa menutupi pangkal sayap. Listrik hitam-emas bergerak di antara bulu ketika sihir dihimpun. Cermin obsidian benteng memantulkan dirinya lebih terang daripada lingkungan, memperkuat ilusi bahwa seluruh menara dibangun untuk satu sosok.','Luciferus angkuh, menghina, dan menuntut pengakuan atas keunggulannya. Ia jarang meninggikan suara karena menganggap perintahnya tidak membutuhkan penjelasan. Penantang yang menolak tunduk menarik perhatiannya sekaligus melukai egonya. Ia bersaing dengan Ksatria Agung Galathius sebagai lawan yang cukup kuat untuk diakui, meski pengakuan itu selalu dibungkus penghinaan. Kesombongan memberinya keteguhan, tetapi juga membuatnya menunda tindakan sampai musuh membuktikan diri di hadapan takhtanya.','Fortress of Pride adalah menara utara berlapis cermin obsidian yang menampilkan kemegahan palsu. Luciferus menunggu di puncak Menara Tanpa Bayangan, setelah penyusup melewati ilusi kesempurnaan diri. Lokasi ini sesuai Benteng Pride Utara dalam data lama. Narasi benteng berlaku sebelum kehancuran peradaban Raksamala.','Mereka yang Tidak Berlutut','Seorang penantang mencapai ruang takhta dengan zirah rusak. Setiap cermin menampilkan dirinya sebagai raja, penyelamat, dan makhluk yang lebih agung daripada rekannya. Luciferus memintanya berlutut agar salah satu gambaran itu menjadi nyata.\n\nPenantang tersebut menutup mata dan mengakui bahwa ia takut serta membutuhkan bantuan orang lain untuk tiba di sana. Cermin-cermin kehilangan sosok sempurna yang dapat ditelan. Luciferus akhirnya berdiri dari takhta. Ia membenci jawaban itu, sebab kerendahan hati telah membawa lawannya melewati ujian yang dirancang untuk kesombongan.','Bhuta',[CHAR+'Luciferus.md',BASE+'Cities & Town/Fortress of Pride.md',BHUTA,KING,THREAT],['Sihir kosmik dan perisai ego belum memiliki spesifikasi gameplay. Rivalitas Galathius mengikuti profil, tanpa menambah duel baru.']),
'Mamon':('Panglima Keserakahan, penguasa korupsi materi, koin terkutuk, dan golem logam karatan. Ia menjadikan keinginan memiliki sebagai beban yang menghancurkan tubuh serta jiwa. Berbeda dari komandan lain, Mamon tercatat menyerang gereja Aqualis untuk merebut bayi kembar yang terikat kutukan Sangrahal.','Mamon berbentuk iblis kurus dengan koin emas tertanam langsung pada daging. Kedua tangan memanjang sebagai cakar pemungut, dan pecahan logam berkarat bergerak di sekitarnya mengikuti sihir magnetis. Tubuhnya tampak rapuh, tetapi lapisan koin membentuk bidang pelindung tidak rata. Dalam pertempuran ia memanggil golem dari besi yang dapat menyatu kembali setelah dihancurkan. Kilau emas pada tubuhnya selalu bercampur noda gelap dan karat.','Mamon licik, posesif, dan menganggap segala sesuatu memiliki harga yang dapat dimanipulasi. Ia menyukai perjanjian yang tampak menguntungkan korban, lalu mengubah kepemilikan menjadi jerat. Ia berkomunikasi melalui koin terkutuk dengan saudagar korup dan memanfaatkan keserakahan tanpa perlu hadir. Saat sesuatu yang diklaimnya direbut, ketenangan itu berubah menjadi kegigihan kejam. Kepatuhannya kepada Sangrahal membawa dirinya ke Aqualis untuk menagih jiwa yang dianggap milik kerajaan.','Fortress of Greed adalah tambang emas kutukan bawah tanah dengan permata, relik, dan koin bernoda darah. Mamon menguasai Tambang Emas Berdarah serta golem penjaganya. Setiap harta yang diambil menambah beban korban. Benteng ini menjadi basisnya sebelum ia muncul di Aqualis dan sebelum Raksamala dihancurkan Hector.','Penagih di Gereja Aqualis','Mamon datang ke gereja Aqualis untuk menagih bayi kembar yang terikat kutukan Sangrahal. Ia membangkitkan mayat, memanggil golem besi, dan menekan para pembela sampai Hector menggunakan Avatar Garuda untuk menahannya. Pecahan golem terus menyatu kembali di bawah sihir sang panglima.\n\nJane, Cassian, dan Hector bertahan bersama sampai kekuatan ungu dari salah satu bayi meledak dan memusnahkan Mamon. Kematian itu mengakhiri penagihan malam tersebut, tetapi juga memperlihatkan bahwa sesuatu yang lebih asing daripada kegelapan Raksamala telah berdiam dalam kehidupan si kembar.','Bhuta',[CHAR+'Mamon.md',BASE+'Cities & Town/Fortress of Greed.md',BHUTA,KING,THREAT,P10],['Kisah merangkum Prologue bab 10. Tuan Midas dan komunikasi koin tetap relasi profil, tetapi tidak dikembangkan menjadi peristiwa baru.']),
'Vraka_The_Wrathful':('Panglima Amarah dan penjaga Fortress of Wrath. Vraka dahulu seorang jenderal Hanorok yang dieksekusi karena taktik perang terlalu brutal; Sangrahal menarik jiwanya dan membentuknya kembali sebagai Bhuta. Kini ia memimpin gelombang invasi Jenggala menuju Swargaloka, membawa dendam lama ke dalam setiap pertempuran.','Vraka adalah monster mutan berotot dengan empat lengan, masing-masing menggenggam kapak jagal raksasa yang meneteskan lava. Api neraka membakar tubuhnya tanpa padam oleh air biasa. Sisa rupa Hanorok masih terbaca pada rahang, postur, dan gerak memanjat, tetapi telah dipelintir oleh pembentukan ulang. Bekas rantai eksekusi melingkari sebagian lengan sebagai pengingat pengkhianatan yang tidak pernah ia lepaskan.','Vraka mudah murka, frontal, dan memandang belas kasihan sebagai penghinaan. Ia mempertahankan kecerdasan seorang jenderal, tetapi dendam membuat strateginya berpusat pada penghancuran total, terutama terhadap Hanorok dan Panglima Wukong. Ia memancing lawan marah agar kehilangan disiplin, karena pertumpahan darah memperkuat benteng serta dirinya. Di balik ledakan emosinya terdapat ingatan yang terus dipelihara; ia memilih menafsirkan setiap penolakan sebagai pengulangan pengkhianatan masa lalu.','Fortress of Wrath berdiri di atas kolam darah mendidih dan berbentuk Arena Jagal Merah. Di sana Jenggala diadu sampai mati, sementara pengaruh Bloodlust mengikis kendali pengunjung. Vraka menjaga kawah benteng sekaligus memimpin serangan berat ke Nusa Sayendra. Lokasi ini menggambarkan masa sebelum Hector menghancurkan komandan dan peradaban Raksamala.','Nama yang Tidak Dimaafkan','Seorang tawanan Hanorok dibawa ke arena dan menyebut nama lama Vraka, berharap ingatan masa lalu menghentikan kapaknya. Sang panglima justru mendengar ejekan dari mereka yang pernah menjatuhkan hukuman. Api pada empat bilahnya membesar.\n\nTawanan itu menolak membalas kemarahan dengan makian. Ia berkata bahwa kekejaman lama tidak menjadi benar hanya karena pengkhianatan yang diterima Vraka juga salah. Sesaat sang panglima berhenti. Lalu ia menghantam arena, bukan karena telah memaafkan, melainkan karena jawaban tersebut mencapai bagian dirinya yang belum sepenuhnya menjadi amarah.','Bhuta',[CHAR+'Vraka The Wrathful.md',BASE+'Cities & Town/Fortress of Wrath.md',BHUTA,KING,THREAT],['Asal Hanorok dan transformasi menjadi Bhuta canon existing. Api yang tidak padam air biasa tidak menjadi blanket immunity; Bloodlust belum dikalibrasi.'])}

def load(p): return json.loads(p.read_text(encoding='utf-8-sig'))
def write(p,o): p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def main():
 a=REPORT/'pre_raksamala_commanders_narrative.json'
 if a.exists(): raise SystemExit('Batch already archived; edit current files directly.')
 ps=sorted(FOLDER.glob('*.json')); assert {p.stem for p in ps}==set(E)
 write(a,{p.relative_to(ROOT).as_posix():p.read_text(encoding='utf-8-sig') for p in FOLDER.iterdir() if p.suffix in ('.md','.json')}); write(REPORT/'pre_raksamala_commanders_hashes.json',{p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in ROOT.rglob('*') if p.is_file() and '.git' not in p.parts and '_audit' not in p.parts and '__pycache__' not in p.parts})
 db={n:load(GAME/'data'/(n+'.json')) for n in ['Enemies','Skills','Items','Weapons','Armors']}
 for p in ps:
  o=load(p); d,f,k,b,st,s,race,sources,u=E[p.stem]; m=[e for e in db['Enemies'] if e and e['name']==o['title']]; assert len(m)==1,p; enemy=m[0]
  t=f'---\ntitle: {o["title"]}\ntags:\n  - Bestiary\n  - Boss\n---\n\n# {o["title"]}\n'
  for h,c in [('Deskripsi',d),('Bentuk',f),('Kepribadian dan Sikap',k),('Kedudukan dan Benteng',b),('Kisah - '+st,s)]: t+=f'\n## {h}\n\n{c}\n'
  for x in sources: assert (ROOT/x).is_file(),x
  t+='\n> Catatan penulisan: Identitas dan benteng mengikuti profil tokoh serta wilayah. Rincian visual tambahan dan kisah non-Prologue merupakan usulan. Acuan: '+'; '.join('['+Path(x).stem.replace('_',' ')+'](../../'+quote(x,safe='/')+')' for x in sources)+'.\n'; p.with_suffix('.md').write_text(t,encoding='utf-8')
  prev={x:o.get(x) for x in ['stat_status','balance_status','source_status']}; o.update(stat_status='BLOCKED',balance_status='BLOCKED',source_status='legacy_with_runtime_observation',race=race)
  o['presentation']={'markdown_role':'lore_only','lore_source':p.with_suffix('.md').relative_to(ROOT).as_posix(),'game_data_source':p.relative_to(ROOT).as_posix(),'narrative_status':'PROPOSED_ADDITIONS','approval':None,'scope':'Seven Raksamala commanders; earlier approvals do not extend.','sync_policy':'Author lore in Markdown; game data stays in JSON.'}; o['lore_review']={'source_archive':a.relative_to(ROOT).as_posix(),'sources':sources,'unresolved':u,'category_note':'Seven sapient fortress commanders under Sangrahal; chronology distinguishes pre-destruction fortresses from post-Hector ruins.','historical_description':o['description']}
  o['runtime_observation']={'status':'OBSERVED_ONLY','source':(GAME/'data/Enemies.json').relative_to(ROOT).as_posix(),'enemy':enemy,'skills':[db['Skills'][x['skillId']] for x in enemy['actions']],'drop_records':[{'database':{1:'Items',2:'Weapons',3:'Armors'}[x['kind']],'record':db[{1:'Items',2:'Weapons',3:'Armors'}[x['kind']]][x['dataId']]} for x in enemy['dropItems'] if x['kind']],'meaning':'Snapshot only; does not establish calibrated balance.'}; o['balance_review']={'stat_status':'BLOCKED','previous_status':prev,'legacy_note':'Legacy numbers preserved; not recalibrated.','authority':'06_Sistem Game & Ekonomi/Pedoman_Pemberian_Stat.md','simulation_result':None,'playtest_evidence':None,'unresolved':['Approved party/gear/progression and encounter targets absent.','Runtime mechanics require review before calibration.']}; write(p,o)
 print('Raksamala commanders narrative batch: 7 pairs.')
if __name__=='__main__': main()
